def step(conn, stop_after_checkpoint=False):
    last = conn.execute("SELECT last_id FROM progress WHERE id=1").fetchone()[0]
    rows = conn.execute("SELECT id, amount_cents FROM orders WHERE id>? ORDER BY id LIMIT 2", (last,)).fetchall()
    if not rows:
        return False
    conn.execute("UPDATE progress SET last_id=? WHERE id=1", (rows[-1][0],))
    conn.commit()
    if stop_after_checkpoint:
        raise RuntimeError("interrupted")
    for row_id, cents in rows:
        conn.execute("UPDATE orders SET amount_micros=? WHERE id=?", (cents * 10000, row_id))
    conn.commit()
    return True
